#include <bits/stdc++.h>
using namespace std;

char str[100005];
int S;

int count_possibilities(int end1, int end2) {
    if (S == 2 && end1 == 0) return 0;
    int X_val = -1;
    if (str[S - 2] == 'X') X_val = end1;
    else {
        if (str[S - 2] != '_') {
            if (value(S - 2) != end1) return 0;
        }
    }
    if (str[S - 1] == 'X') {
        if (X_val != -1 && end2 != X_val) return 0;
        else X_val = end2;
    } else {
        if (str[S - 1] != '_') {
            if (value(S - 1) != end2) return 0;
        }
    }
    int total = 1;
    for (int i = 0; i < S - 2; i++) {
        if (i == 0) {
            if (str[i] == 'X' && X_val == 0) return 0;
            if (value(i) == 0) return 0;
        }
        if (str[i] == '_') {
            if (i == 0) total *= 9;
            else total *= 10;
        }
        if (str[i] == 'X') {
            if (X_val != -1) continue;
            else {
                X_val = 10;
                if (i == 0) total *= 9;
                else total *= 10;
            }
        }
    }
    return total;
}

bool isDigit(int pos) {
    if (str[pos] == '_' || str[pos] == 'X') return false;
    else return true;
}

int value(int pos) {
    if (!isDigit(pos)) return -1;
    return str[pos] - '0';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string input;
    getline(cin, input);
    S = (int)input.size();
    for (int i = 0; i < S; i++) {
        str[i] = input[i];
    }
    int ans = 0;
    if (S == 1) {
        if (str[0] == 'X' || str[0] == '_' || (str[0] >= '0' && str[0] <= '9' && str[0] - '0' == 0))
            ans = 1;
    } else {
        ans += count_possibilities(2, 5);
        ans += count_possibilities(5, 0);
        ans += count_possibilities(7, 5);
        ans += count_possibilities(0, 0);
    }
    cout << ans << "\n";
    return 0;
}

